CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY, en TEXT DEFAULT '', ar TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS skills (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name_en TEXT NOT NULL, name_ar TEXT DEFAULT '', category_en TEXT DEFAULT '', category_ar TEXT DEFAULT '', level TEXT DEFAULT '', icon TEXT DEFAULT '', published INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS certifications (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name_en TEXT NOT NULL, name_ar TEXT DEFAULT '', status_en TEXT DEFAULT '', status_ar TEXT DEFAULT '', desc_en TEXT DEFAULT '', desc_ar TEXT DEFAULT '', score TEXT DEFAULT '', provider TEXT DEFAULT '', date_en TEXT DEFAULT '', date_ar TEXT DEFAULT '', credential_url TEXT DEFAULT '', logo_url TEXT DEFAULT '', featured INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title_en TEXT NOT NULL, title_ar TEXT DEFAULT '', desc_en TEXT DEFAULT '', desc_ar TEXT DEFAULT '', published INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS approach_steps (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title_en TEXT NOT NULL, title_ar TEXT DEFAULT '', desc_en TEXT DEFAULT '', desc_ar TEXT DEFAULT '', published INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS navigation (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, label_en TEXT NOT NULL, label_ar TEXT DEFAULT '', href TEXT NOT NULL, target TEXT DEFAULT '', published INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
